// 550ms long-press marking and reversible elimination, adapted from xuhang-mvp.
const marksByQuestion=questions.map(()=>[]),excludedByQuestion=questions.map(()=>new Set());
const stemElement=document.querySelector('#stem');
let stemPress=null,optionPress=null,armed=false,pressOrigin=null,suppressOption=null,markRangeToToggle=null;
function mergeRanges(ranges){const out=[];for(const r of [...ranges].sort((a,b)=>a.start-b.start)){const last=out[out.length-1];if(last&&r.start<=last.end)last.end=Math.max(last.end,r.end);else out.push({...r})}return out}
function drawMarks(){const q=questions[current],source=q.stem+q.sentence;stemElement.replaceChildren();let offset=0;for(const text of [q.stem,q.sentence]){const line=document.createElement('span');if(offset)line.style.cssText='display:block;margin-top:12px;font-weight:400';for(let i=0;i<text.length;i++){const ch=document.createElement('span');ch.dataset.char=offset;ch.tabIndex=-1;ch.textContent=text[i];if(marksByQuestion[current].some(r=>offset>=r.start&&offset<r.end))ch.className='ink-mark';line.append(ch);offset++}stemElement.append(line)}}
function toggleMarkedRange(a,b){const existing=marksByQuestion[current],overlaps=existing.some(r=>a<r.end&&b>r.start);if(overlaps){const next=[];for(const r of existing){if(b<=r.start||a>=r.end)next.push(r);else{if(r.start<a)next.push({start:r.start,end:a});if(r.end>b)next.push({start:b,end:r.end})}}marksByQuestion[current]=next}else marksByQuestion[current]=mergeRanges([...existing,{start:a,end:b}]);drawMarks()}
function wordRange(i){const text=questions[current].stem+questions[current].sentence;let a=i,b=i;if(/[a-zA-Z]/.test(text[i])){while(a>0&&/[a-zA-Z]/.test(text[a-1]))a--;while(b+1<text.length&&/[a-zA-Z]/.test(text[b+1]))b++}return[a,b+1]}
function resetStem(){clearTimeout(stemPress);stemPress=null;armed=false;pressOrigin=null;markRangeToToggle=null;stemElement.classList.remove('mark-ready')}
function charAt(e){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-char]');return target&&stemElement.contains(target)?Number(target.dataset.char):null}
function beginMark(i){armed=true;markRangeToToggle=wordRange(i);stemElement.classList.add('mark-ready')}
stemElement.oncontextmenu=e=>e.preventDefault();
stemElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;const hit=e.target.closest("[data-char]");const i=hit?Number(hit.dataset.char):charAt(e);if(i===null)return;resetStem();pressOrigin={x:e.clientX,y:e.clientY};stemPress=setTimeout(()=>{stemPress=null;beginMark(i)},550)});
window.addEventListener('pointermove',e=>{if(pressOrigin&&!armed&&Math.hypot(e.clientX-pressOrigin.x,e.clientY-pressOrigin.y)>10)resetStem();if(optionPress&&Math.hypot(e.clientX-optionPress.x,e.clientY-optionPress.y)>10){clearTimeout(optionPress.timer);optionPress=null}});
function stopPress(){clearTimeout(stemPress);stemPress=null;pressOrigin=null;stemElement.classList.remove('mark-ready');if(armed&&markRangeToToggle)toggleMarkedRange(...markRangeToToggle);armed=false;markRangeToToggle=null;if(optionPress){clearTimeout(optionPress.timer);optionPress=null}}
window.addEventListener('pointerup',stopPress);window.addEventListener('pointercancel',stopPress);
function updateExcluded(){document.querySelectorAll('.option').forEach((el,i)=>{const excluded=excludedByQuestion[current].has(i);el.classList.toggle('excluded',excluded);el.title=excluded?'已排除，再次长按恢复':'长按排除';el.querySelector('input').setAttribute('aria-label',letters[i]+' '+questions[current].options[i]+(excluded?'，已排除':''))})}
function toggleEliminate(i){const excluded=excludedByQuestion[current];if(excluded.has(i))excluded.delete(i);else{excluded.add(i);if(answers[current]===i){answers[current]=null;document.querySelectorAll('[name=answer]').forEach(r=>r.checked=false);renderPanel()}}updateExcluded()}
function bindOptions(){document.querySelectorAll('.option').forEach((el,i)=>{el.lastElementChild.classList.add('option-text');const radio=el.querySelector('input'),originalChange=radio.onchange;radio.onchange=e=>{if(excludedByQuestion[current].has(i)){document.querySelectorAll('[name=answer]').forEach((r,n)=>r.checked=answers[current]===n);return}originalChange(e)};el.oncontextmenu=e=>e.preventDefault();el.addEventListener('pointerdown',e=>{if(e.button!==0)return;suppressOption=null;if(optionPress)clearTimeout(optionPress.timer);optionPress={x:e.clientX,y:e.clientY,timer:setTimeout(()=>{suppressOption=i;toggleEliminate(i);optionPress=null},550)}});el.addEventListener('click',e=>{if(suppressOption===i||excludedByQuestion[current].has(i)){e.preventDefault();e.stopImmediatePropagation();setTimeout(()=>{el.querySelector('input').checked=answers[current]===i},0)}},true);el.addEventListener('keydown',e=>{if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();toggleEliminate(i)}})});updateExcluded()}
const baseRender=render;render=function(){resetStem();if(optionPress)clearTimeout(optionPress.timer);optionPress=null;suppressOption=null;baseRender();drawMarks();bindOptions()};render();
window.addEventListener('blur',()=>{resetStem();if(optionPress)clearTimeout(optionPress.timer);optionPress=null});



stemElement.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){const hit=e.target.closest("[data-char]");if(hit){e.preventDefault();const [a,b]=wordRange(Number(hit.dataset.char));toggleMarkedRange(a,b)}}});
